"""Missingness-topology-aware column permutation for character-prefix caching."""

import heapq
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    def __init__(self, df: pd.DataFrame = None):
        """Store the optional source frame and the latest row-specific orders."""
        self.df = df
        self._last_orders = None

    @staticmethod
    def _cell_string(value) -> str:
        """Convert one cell to evaluator-compatible text without changing the cell."""
        missing = pd.isna(value)
        if isinstance(missing, (bool, np.bool_)) and bool(missing):
            return ""
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return the exact common-prefix length using bounded binary search."""
        if left == right:
            return len(left)
        lo, hi = 0, min(len(left), len(right))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if left[:mid] == right[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _score(cls, strings) -> int:
        """Compute ideal character-Trie reuse from lexicographically adjacent rows."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        total = 0
        previous = ordered[0]
        for current in ordered[1:]:
            total += cls._lcp(previous, current)
            previous = current
        return total

    @staticmethod
    def _positions(columns):
        """Map stringified column names to their physical positions."""
        result = {}
        for index, name in enumerate(columns):
            result.setdefault(str(name), []).append(index)
        return result

    @classmethod
    def _blocks(cls, width, columns, requested):
        """Build connected column-merge blocks with deterministic union-find."""
        parent = list(range(width))

        def find(value):
            while parent[value] != value:
                parent[value] = parent[parent[value]]
                value = parent[value]
            return value

        positions = cls._positions(columns)
        for pair in requested or []:
            if len(pair) != 2:
                continue
            left = positions.get(str(pair[0]), [])
            right = positions.get(str(pair[1]), [])
            if len(left) == 1 and len(right) == 1:
                a, b = find(left[0]), find(right[0])
                if a != b:
                    parent[b] = a

        groups = {}
        for index in range(width):
            groups.setdefault(find(index), []).append(index)
        return sorted((sorted(group) for group in groups.values()),
                      key=lambda group: group[0])

    @classmethod
    def _repair(cls, width, preference, columns, dependencies, blocks):
        """Repair a preferred order into a dependency- and merge-valid topological order."""
        positions = cls._positions(columns)
        edges = []
        seen = set()

        def add(left, right):
            if left != right and (left, right) not in seen:
                seen.add((left, right))
                edges.append((left, right))

        for pair in dependencies or []:
            if len(pair) != 2:
                continue
            left = positions.get(str(pair[0]), [])
            right = positions.get(str(pair[1]), [])
            if len(left) == 1 and len(right) == 1:
                add(left[0], right[0])

        for block in blocks:
            for left, right in zip(block, block[1:]):
                add(left, right)

        outgoing = [[] for _ in range(width)]
        indegree = [0] * width
        for left, right in edges:
            outgoing[left].append(right)
            indegree[right] += 1

        rank = {column: position for position, column in enumerate(preference)}
        heap = [
            (rank.get(column, width + column), column)
            for column in range(width)
            if indegree[column] == 0
        ]
        heapq.heapify(heap)

        result = []
        while heap:
            _, node = heapq.heappop(heap)
            result.append(node)
            for successor in outgoing[node]:
                indegree[successor] -= 1
                if indegree[successor] == 0:
                    heapq.heappush(
                        heap, (rank.get(successor, width + successor), successor)
                    )

        return result if len(result) == width else list(preference)

    @staticmethod
    def _frequency_order(text, rows, blocks):
        """Rank blocks by length-weighted repeated values on the supplied row subset."""
        width = text.shape[1]
        row_count = len(rows)
        scores = np.zeros(width, dtype=np.int64)

        # A dictionary per column avoids pandas object construction in cohort scans.
        for column in range(width):
            counts = {}
            for row in rows:
                value = text[row, column]
                counts[value] = counts.get(value, 0) + 1
            total = 0
            for value, count in counts.items():
                total += len(value) * count * (count - 1)
            scores[column] = total

        block_scores = [
            (sum(int(scores[column]) for column in block), block[0], block)
            for block in blocks
        ]
        block_scores.sort(key=lambda item: (-item[0], item[1]))
        return [column for _, _, block in block_scores for column in block]

    @staticmethod
    def _serialize(text, row_orders):
        """Serialize each source row using its own selected column permutation."""
        return [
            "".join(text[row, column] for column in row_orders[row])
            for row in range(text.shape[0])
        ]

    @staticmethod
    def _materialize(df, source, row_orders, serialized):
        """Sort output rows by serialized text and preserve each row's public order."""
        row_order = sorted(
            range(len(serialized)), key=lambda row: (serialized[row], row)
        )
        values = np.empty(source.shape, dtype=object)
        public_orders = []

        for output_row, source_row in enumerate(row_order):
            order = row_orders[source_row]
            values[output_row, :] = [source[source_row, column] for column in order]
            public_orders.append([df.columns[column] for column in order])

        result = pd.DataFrame(
            values,
            index=df.index.take(row_order),
            columns=list(df.columns),
        )
        return result, public_orders

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List]]:
        """Select a global order and a missingness-cohort order, then keep the better candidate."""
        if not isinstance(df, pd.DataFrame):
            raise TypeError("df must be a pandas DataFrame")

        rows, width = df.shape
        if rows == 0 or width == 0:
            result = df.copy()
            orders = [[] for _ in range(rows)]
            self._last_orders = orders
            return result, orders

        source = df.to_numpy(dtype=object, copy=True)
        text = np.empty((rows, width), dtype=object)
        masks = []

        for row in range(rows):
            mask = []
            for column in range(width):
                value = source[row, column]
                missing = pd.isna(value)
                is_missing = (
                    isinstance(missing, (bool, np.bool_)) and bool(missing)
                )
                mask.append(is_missing)
                text[row, column] = "" if is_missing else str(value)
            masks.append(tuple(mask))

        columns = list(df.columns)
        blocks = self._blocks(width, columns, col_merge)
        all_rows = list(range(rows))

        # Incumbent global schema.
        global_preference = self._frequency_order(text, all_rows, blocks)
        global_order = self._repair(
            width, global_preference, columns, one_way_dep, blocks
        )
        global_orders = [global_order[:] for _ in range(rows)]
        global_serialized = self._serialize(text, global_orders)
        best_score = self._score(global_serialized)
        best_orders = global_orders
        best_serialized = global_serialized

        # Missingness topology cohorts, limited to the eight largest repeated masks.
        cohorts = {}
        for row, mask in enumerate(masks):
            cohorts.setdefault(mask, []).append(row)
        selected = sorted(
            (members for members in cohorts.values() if len(members) >= 2),
            key=lambda members: (-len(members), members[0]),
        )[:8]

        if selected:
            cohort_orders = [global_order[:] for _ in range(rows)]
            for members in selected:
                preference = self._frequency_order(text, members, blocks)
                order = self._repair(
                    width, preference, columns, one_way_dep, blocks
                )
                for row in members:
                    cohort_orders[row] = order[:]

            candidate_serialized = self._serialize(text, cohort_orders)
            candidate_score = self._score(candidate_serialized)
            if candidate_score > best_score:
                best_score = candidate_score
                best_orders = cohort_orders
                best_serialized = candidate_serialized

        result, public_orders = self._materialize(
            df, source, best_orders, best_serialized
        )
        if result.shape != df.shape:
            raise RuntimeError("Reordering changed DataFrame shape")

        self._last_orders = public_orders
        return result, public_orders

